SELECT a.*, ROW_NUMBER() OVER (PARTITION BY REPORT_MONTH ORDER BY FLAGGED_GROSS_INR DESC, RULE_FLAGS DESC, ACCOUNT_ID) AS EXPOSURE_RANK, SUM(FLAGGED_GROSS_INR) OVER (PARTITION BY REPORT_MONTH) AS MONTH_FLAGGED_GROSS_INR FROM ( SELECT ACCOUNT_ID, TO_CHAR(TRANSACTION_DATE,'YYYY-MM') AS REPORT_MONTH, COUNT(*) AS TRANSACTION_COUNT, SUM(ABS(AMOUNT)) AS GROSS_ACTIVITY_INR, SUM(AMOUNT) AS NET_ACTIVITY_INR, AVG(RISK_SCORE) AS AVG_RULE_SCORE, SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) AS RULE_FLAGS, SUM(CASE WHEN RISK_SCORE > 60 THEN ABS(AMOUNT) ELSE 0 END) AS FLAGGED_GROSS_INR, 100.0 * SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) / COUNT(*) AS FLAG_RATE_PCT, SUM(CASE WHEN RISK_SCORE > 60 AND ABS(AMOUNT) >= 5000 THEN 1 ELSE 0 END) AS HIGH_VALUE_FLAGS, CASE WHEN SUM(CASE WHEN RISK_SCORE > 60 THEN ABS(AMOUNT) ELSE 0 END) >= 10000 OR MAX(CASE WHEN RISK_SCORE >= 85 AND ABS(AMOUNT) >= 5000 THEN 1 ELSE 0 END) = 1 THEN 'P1' WHEN SUM(CASE WHEN RISK_SCORE > 60 THEN 1 ELSE 0 END) > 0 THEN 'P2' ELSE 'P3' END AS DEMO_PRIORITY FROM GOLD.FRAUD_DETECTION_MODEL_GOLD GROUP BY ACCOUNT_ID, TO_CHAR(TRANSACTION_DATE,'YYYY-MM') ) a
